360		if err != nil {
361			t.Fatalf("second parse after failure: %v", err)
362		}
363		assertLines(t, [][]string{{"value", "second"}}, lines)
364	
365		// mutating the caller's map after Parse must not change a result
366		// that was computed from the snapshot
367		tree := mkTree("frozen")
368		blocks, err := Parse("Caddyfile", tree["Caddyfile"], tree)
369		if err != nil {
370			t.Fatalf("unexpected error: %v", err)
371		}
