373		assertLines(t, [][]string{{"value", "frozen"}}, flattenBlocks(blocks))
374	
375		// concurrent parses with distinct trees over the same filenames;
376		// every worker must observe only its own argument value
377		const workers = 32
378		const iterations = 20
379		var wg sync.WaitGroup
380		errCh := make(chan error, workers)
381		for w := 0; w < workers; w++ {
382			wg.Add(1)
383			go func(w int) {
384				defer wg.Done()
385				want := "worker-" + strconv.Itoa(w)
386				for i := 0; i < iterations; i++ {
387					tree := mkTree(want)
388					blocks, perr := Parse("Caddyfile", tree["Caddyfile"], tree)
389					if perr != nil {
390						errCh <- perr
391						return
392					}
393					got := flattenBlocks(blocks)
394					if len(got) != 1 || len(got[0]) != 2 || got[0][1] != want {
395						errCh <- fmt.Errorf("parallel parse observed foreign arguments: want %q got %v", want, got)
396						return
397					}
398				}
399			}(w)
400		}
401		wg.Wait()
402		close(errCh)
403		for err := range errCh {
404			t.Fatal(err)
405		}
406	}
