445	func assertLines(t *testing.T, want, got [][]string) {
446		t.Helper()
447		if len(got) != len(want) {
448			t.Fatalf("expected %d directive lines, got %d: %v", len(want), len(got), got)
449		}
450		for i := range want {
451			if len(got[i]) != len(want[i]) {
452				t.Fatalf("line %d: expected %v, got %v", i, want[i], got[i])
453			}
454			for j := range want[i] {
455				if got[i][j] != want[i][j] {
456					t.Fatalf("line %d, arg %d: expected %q, got %q", i, j, want[i][j], got[i][j])
457				}
458			}
459		}
460	}
461

