	matches, err := fs.Glob(r.fsys, normalizeImportPath(pattern))
	if err != nil {
		return nil, err
	}
	normalized := make([]string, len(matches))
	for i, m := range matches {
		normalized[i] = normalizeImportPath(m)
	}
	sort.Strings(normalized)
	return normalized, nil
}

